#pragma once

#include <cstddef>
#include <cstdint>
#include <span>

// Generated by CMake from third_party/fonts/*.ttf (see the embed step in CMakeLists.txt).
extern const unsigned char kInterFontData[];
extern const unsigned long long kInterFontSize;
extern const unsigned char kMonoFontData[];
extern const unsigned long long kMonoFontSize;

namespace trace {

// The fonts compiled into the program, as the bytes of their TrueType files. The Text tool draws with them.
inline std::span<const std::uint8_t> interFontBytes() noexcept {
    return {kInterFontData, static_cast<std::size_t>(kInterFontSize)};
}
inline std::span<const std::uint8_t> monoFontBytes() noexcept {
    return {kMonoFontData, static_cast<std::size_t>(kMonoFontSize)};
}

} // namespace trace
